<?php
namespace App\Controllers\Admin;
use App\Core\Controller;use App\Core\Auth;use App\Core\Database;use App\Core\Session;use App\Core\Upload;use App\Core\Audit;
final class CauseAdminController extends Controller
{
 public function index():void{$u=Auth::requireAdmin();Auth::enforce('manage_content');$total=(int)(Database::one('SELECT COUNT(*) c FROM campaign_categories')['c']??0);$pagination=admin_pager($total,12);$rows=Database::all('SELECT * FROM campaign_categories ORDER BY sort_order,id LIMIT '.(int)$pagination['per_page'].' OFFSET '.(int)$pagination['offset']);$this->view('admin/causes',['user'=>$u,'causes'=>$rows,'pagination'=>$pagination,'adminTitle'=>'Cause Areas'],'admin');}
 public function save():void{$this->requirePost();$u=Auth::requireAdmin();Auth::enforce('manage_content');$id=(int)($_POST['id']??0);$name=substr(trim($_POST['name']??''),0,120);if(strlen($name)<2){Session::flash('error','Cause name is required.');redirect('admin/causes');}$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$name),'-'));$img=null;try{if(isset($_FILES['image'])&&($_FILES['image']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE)$img=Upload::publicImage($_FILES['image'],'causes');}catch(\Throwable $e){Session::flash('error',$e->getMessage());redirect('admin/causes');}if($id){$old=Database::one('SELECT image_path FROM campaign_categories WHERE id=?',[$id]);$img=$img?:($old['image_path']??null);Database::exec('UPDATE campaign_categories SET name=?,slug=?,description=?,icon=?,image_path=?,is_active=?,sort_order=? WHERE id=?',[$name,$slug,substr(trim($_POST['description']??''),0,600),substr(trim($_POST['icon']??'♡'),0,40),$img,isset($_POST['is_active'])?1:0,(int)($_POST['sort_order']??0),$id]);}else{$id=Database::insert('INSERT INTO campaign_categories(name,slug,description,icon,image_path,is_active,sort_order) VALUES(?,?,?,?,?,?,?)',[$name,$slug,substr(trim($_POST['description']??''),0,600),substr(trim($_POST['icon']??'♡'),0,40),$img,isset($_POST['is_active'])?1:0,(int)($_POST['sort_order']??0)]);}Audit::write((int)$u['id'],'CAUSE_SAVED','causes',$id,'Cause area saved');Session::flash('success','Cause area saved.');redirect('admin/causes');}
 public function delete():void{$this->requirePost();$u=Auth::requireAdmin();Auth::enforce('manage_content');$id=(int)($_POST['id']??0);Database::exec('DELETE FROM campaign_categories WHERE id=?',[$id]);Audit::write((int)$u['id'],'DELETE','causes',$id,'Cause area deleted');Session::flash('success','Cause area deleted.');redirect('admin/causes');}

 public function toggle():void{$this->requirePost();$u=Auth::requireAdmin();Auth::enforce('manage_content');$id=(int)($_POST['id']??0);$r=Database::one('SELECT is_active FROM campaign_categories WHERE id=?',[$id]);if($r)Database::exec('UPDATE campaign_categories SET is_active=? WHERE id=?',[(int)!((int)$r['is_active']),$id]);Audit::write((int)$u['id'],'CAUSE_ACTIVE_STATE','causes',$id,'Cause area active state toggled');Session::flash('success','Cause area active/inactive state updated.');redirect('admin/causes');}
}
